/* ---------- hero: the page paves itself ---------- */
const PRESETS = [
  {name:"Classic", sw:["grey","red"], cfg:{pattern:"zig", field:"grey", accent:"red", mode:"band", mix:.25, border:false, borderC:"red", light:"noon"}},
  {name:"Heritage", sw:["red","grey"], cfg:{pattern:"herringbone", field:"red", accent:"red", mode:"solid", mix:.25, border:true, borderC:"grey", light:"noon"}},
  {name:"Garden", sw:["yellow","red"], cfg:{pattern:"combo5", field:"yellow", accent:"red", mode:"blend", mix:.18, border:false, borderC:"red", light:"noon"}},
  {name:"Monsoon", sw:["grey","yellow"], cfg:{pattern:"ishape", field:"grey", accent:"yellow", mode:"lanes", mix:.25, border:false, borderC:"red", light:"rain"}},
  {name:"Evening", sw:["orange","grey"], cfg:{pattern:"basket", field:"orange", accent:"grey", mode:"checker", mix:.25, border:true, borderC:"grey", light:"dusk"}}
];
let heroIdx=0;
const repave=document.querySelector(".repave");
PRESETS.forEach((p,i)=>{ const b=document.createElement("button"); b.type="button"; b.id="pre-"+i; b.setAttribute("aria-pressed", i===0);
  b.innerHTML='<i style="background:'+COLOURS[p.sw[0]].hex+'"></i><i style="background:'+COLOURS[p.sw[1]].hex+';margin-left:-10px"></i>'+p.name; repave.appendChild(b); });
repave.addEventListener("click", e => { const b=e.target.closest("button"); if(!b) return; heroIdx=+b.id.split("-")[1]; press(repave,b); paintHero(true); });
const SMALL = () => innerWidth <= 760;
function paintHero(anim){ paint($("heroCanvas"), PRESETS[heroIdx].cfg, {viewW: SMALL()?4200:6500, animate:anim, maxDpr: SMALL()?1:1.25, seed:5+heroIdx}); }

/* ---------- studio ---------- */
const S = {shape:"zigzag", pattern:"zig", field:"grey", accent:"red", mode:"band", mix:.25, border:true, borderC:"red", light:"noon", view:"top"};
const MODES = [["solid","Single colour"],["band","Diagonal band"],["checker","Chequer"],["blend","Blend"],["lanes","Bay lines"]];
function dotsInto(el, prefix, selected){
  el.innerHTML = Object.keys(COLOURS).map(c=>'<button type="button" class="dot" id="'+prefix+'-'+c+'" data-c="'+c+'" aria-label="'+COLOURS[c].name+'" title="'+COLOURS[c].name+'" aria-pressed="'+(c===selected)+'" style="background:'+COLOURS[c].hex+'"></button>').join("");
}
function buildStudio(){
  $("sShape").innerHTML = PRODUCTS.filter(p=>p.patterns.length).map(p=>'<button type="button" class="chip" id="ss-'+p.id+'" data-v="'+p.id+'" aria-pressed="'+(p.id===S.shape)+'">'+p.name+'</button>').join("");
  $("sPattern").innerHTML = P(S.shape).patterns.map(k=>'<button type="button" class="chip" id="sp-'+k+'" data-v="'+k+'" aria-pressed="'+(k===S.pattern)+'">'+PATTERN_NAMES[k]+'</button>').join("");
  $("sMode").innerHTML = MODES.map(m=>'<button type="button" class="chip" id="sm-'+m[0]+'" data-v="'+m[0]+'" aria-pressed="'+(m[0]===S.mode)+'">'+m[1]+'</button>').join("");
  dotsInto($("sField"),"sf",S.field); dotsInto($("sAccent"),"sa",S.accent); dotsInto($("sBorder"),"sb",S.borderC);
  $("accentRow").hidden = S.mode==="solid"; $("mixWrap").hidden = S.mode!=="blend";
  $("sBorder").style.opacity = S.border ? 1 : .35;
  press($("b-on").parentElement, $(S.border?"b-on":"b-off"));
}
function designCode(){ return "SP-"+P(S.shape).code+"-"+S.pattern.slice(0,3).toUpperCase()+"-"+S.field[0].toUpperCase()+(S.mode!=="solid"? "/"+S.accent[0].toUpperCase()+":"+S.mode.slice(0,3).toUpperCase():"")+(S.border?"-B"+S.borderC[0].toUpperCase():""); }
let lastCounts={};
function renderStudio(anim){
  const stage=$("studioStage"); stage.classList.toggle("walk", S.view==="walk");
  const res = paint($("studioCanvas"), S, {viewW: S.view==="walk"?(SMALL()?5200:7600):(SMALL()?3000:4200), animate:anim, seed:11, maxDpr: S.view==="walk"?(SMALL()?1:1.25):(SMALL()?1.5:2)});
  lastCounts = res.counts; $("designCode").textContent=designCode(); updateQty();
}
function updateQty(){
  const area=Math.max(0, parseFloat($("sArea").value)||0), p=P(S.shape);
  const per = p.per || (1/p.perSet*5);  /* combo: blocks per sq ft */
  const total = Math.ceil(area*1.05*per);
  $("sTotal").textContent = area ? fmt(total) : "—";
  /* split by colour, from the blocks counted in the preview; the border takes about 2 blocks per running foot of edge */
  const sum=Object.values(lastCounts).reduce((a,b)=>a+b,0)||1, parts=[];
  let borderBlocks=0;
  if(S.border && area){ const side=Math.sqrt(area); borderBlocks=Math.min(total*.4, Math.round(4*side*2*1.05*(per/4.6)*4.6/2)); }
  const fieldTotal = total-borderBlocks;
  Object.entries(lastCounts).forEach(([hex,n])=>{ const name=Object.keys(COLOURS).find(k=>COLOURS[k].hex===hex); parts.push([name, Math.round(fieldTotal*n/sum)]); });
  if(borderBlocks){ const e=parts.find(q=>q[0]===S.borderC); if(e) e[1]+=borderBlocks; else parts.push([S.borderC,borderBlocks]); }
  parts.sort((a,b)=>b[1]-a[1]);
  $("sSplit").innerHTML = area ? parts.map(q=>'<span><i style="background:'+COLOURS[q[0]].hex+'"></i>'+COLOURS[q[0]].name+' <b class="num">'+fmt(q[1])+'</b></span>').join("") : "";
  const msg = "Hello Satyam Pavers, I designed this in your pattern studio:\n"+designCode()+"\nBlock: "+p.name+" ("+PATTERN_NAMES[S.pattern]+")\nColours: "+parts.map(q=>COLOURS[q[0]].name+" "+fmt(q[1])).join(", ")+"\nArea: "+fmt(area)+" sq ft (about "+fmt(total)+" blocks)\nPlease send me details.";
  $("sSend").href = waLink(msg);
  S.split = parts; S.total = total;
}
$("sShape").addEventListener("click", e=>{ const b=e.target.closest("[data-v]"); if(!b) return; S.shape=b.dataset.v; S.pattern=P(S.shape).patterns[0]; buildStudio(); renderStudio(true); });
$("sPattern").addEventListener("click", e=>{ const b=e.target.closest("[data-v]"); if(!b) return; S.pattern=b.dataset.v; buildStudio(); renderStudio(true); });
$("sMode").addEventListener("click", e=>{ const b=e.target.closest("[data-v]"); if(!b) return; S.mode=b.dataset.v; buildStudio(); renderStudio(false); });
$("sField").addEventListener("click", e=>{ const b=e.target.closest("[data-c]"); if(!b) return; S.field=b.dataset.c; buildStudio(); renderStudio(false); });
$("sAccent").addEventListener("click", e=>{ const b=e.target.closest("[data-c]"); if(!b) return; S.accent=b.dataset.c; buildStudio(); renderStudio(false); });
$("sBorder").addEventListener("click", e=>{ const b=e.target.closest("[data-c]"); if(!b) return; S.borderC=b.dataset.c; S.border=true; buildStudio(); renderStudio(false); });
$("b-on").parentElement.addEventListener("click", e=>{ const b=e.target.closest("[data-b]"); if(!b) return; S.border=b.dataset.b==="1"; buildStudio(); renderStudio(false); });
