let cur=null;
let dView=null; /* index into the detail gallery */
function galleryOf(p){
  const g=(PHOTOS[p.id]||[]).map(x=>({src:photoSrc(x.f), cap:x.cap, real:x.kind}));
  if(!p.noRender) Object.keys(COLOURS).forEach(c=>g.push({src:imgOf(p.id,c), cap:p.name+" laid in "+nameOf(c).toLowerCase()+" (preview)", real:false}));
  if(!g.length) g.push({src:ROOT+"assets/img/stock/placeholder.webp", cap:p.full, real:false});
  return g;
}
