  $("dThumbs").innerHTML = g.length>1 ? g.map((x,i)=>'<button type="button" id="dt-'+i+'" data-i="'+i+'" aria-pressed="'+(i===dView)+'" aria-label="'+x.cap+'"><img src="'+x.src+'" alt=""></button>').join("") : "";
