  $("dColours").innerHTML = coloursOf(p).map(c=>'<button type="button" class="dot" id="dc-'+c+'" data-c="'+c+'" aria-label="'+nameOf(c)+'" title="'+nameOf(c)+'" aria-pressed="'+(c===p.c)+'" style="background:'+hexOf(c)+'"></button>').join("");
  const cl = coloursOf(p).map(nameOf).join(", ");
  const rows=[["Size",'<span class="mono">'+p.size+'</span>'],["Thickness",'<span class="mono">'+(p.thick.length?p.thick.join(" / ")+" mm":"On request")+'</span>'],["Blocks per sq ft",'<span class="mono">'+(p.per?"≈ "+p.per:(p.perSet?"1 set per "+p.perSet+" sq ft":(p.id==="curved"?"Sold by running foot":"Ask us")))+'</span>'],["Load",p.load],["Laying patterns",p.patterns.map(k=>PATTERN_NAMES[k]).join(", ")||(p.id==="curved"?"Straight runs and curves":(p.lay||"Ask us"))],["Colours",cl+(p.noRender||cl.includes("Brown")?"":(cl.includes("Black")?"; brown on order":"; black and brown on order"))]];
