$("loadTicks").innerHTML = LOADS.map((l,i)=>'<button type="button" id="lt-'+i+'" data-i="'+i+'" aria-pressed="'+(i===2)+'"><svg viewBox="0 0 34 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+l.icon+'</svg>'+l.short+'</button>').join("");
let LOAD=2;
function renderLoad(){
  const L=LOADS[LOAD]; $("loadRange").value=LOAD; $("loadRange").setAttribute("aria-valuetext", L.name);
  $("loadTicks").querySelectorAll("button").forEach((b,i)=>b.setAttribute("aria-pressed", i===LOAD));
  $("loadRec").innerHTML = '<div class="label">'+L.name+'</div><div class="big num"><div><b>'+L.mm+' mm</b><span>Block thickness</span></div><div><b class="mono" style="font-family:var(--display)">'+L.grade+'</b><span>Strength grade</span></div><div><b>'+L.base+' mm</b><span>Stone sub-base</span></div></div>'+
    '<p style="color:var(--muted)">'+L.eg+'.</p><div><span class="label">Best blocks</span><div class="chips" style="margin-top:8px">'+L.picks.map(id=>'<button type="button" class="chip" data-open="'+id+'">'+P(id).name+'</button>').join("")+'</div></div>'+
    '<div class="row2"><a class="btn btn-ink" href="#quote" id="loadToQuote">Enquire for this load</a></div>';
  drawSection(L);
}
function drawSection(L){
  const k=.62, x0=20, w=360, top=24;
  const layers=[["Paver block",L.mm,"#9E4732"],["Bedding sand",30,"#D9C9A8"],["Crushed stone sub-base",L.base,"#8D877C"]];
  let y=top, out='';
  const pv=L.mm*k;
  for(let x=x0;x<x0+w;x+=60){ out+='<rect x="'+(x+1)+'" y="'+y+'" width="58" height="'+pv+'" fill="#9E4732"/><rect x="'+(x+1)+'" y="'+y+'" width="58" height="3" fill="rgba(255,255,255,.25)"/>'; }
  const lbl=(yy,h,t,mm)=>'<line x1="'+(x0+w+10)+'" y1="'+yy+'" x2="'+(x0+w+10)+'" y2="'+(yy+h)+'" stroke="currentColor" stroke-width="1"/><line x1="'+(x0+w+6)+'" y1="'+yy+'" x2="'+(x0+w+14)+'" y2="'+yy+'" stroke="currentColor"/><text x="'+(x0+w+22)+'" y="'+(yy+h/2-2)+'" fill="currentColor" font-size="13" font-family="Mukta,sans-serif">'+t+'</text><text x="'+(x0+w+22)+'" y="'+(yy+h/2+14)+'" fill="currentColor" font-size="12" font-family="IBM Plex Mono,monospace" opacity=".7">'+mm+' mm</text>';
  out+=lbl(y,pv,layers[0][0],L.mm); y+=pv;
  const sd=30*k; out+='<rect x="'+x0+'" y="'+y+'" width="'+w+'" height="'+sd+'" fill="#D9C9A8"/>'+lbl(y,sd,"Bedding sand",30); y+=sd;
  const bs=L.base*k; out+='<rect x="'+x0+'" y="'+y+'" width="'+w+'" height="'+bs+'" fill="#8D877C"/>';
  const r=rng(L.base); for(let i=0;i<L.base/2;i++) out+='<circle cx="'+(x0+5+r()*(w-10))+'" cy="'+(y+4+r()*(bs-8))+'" r="'+(1.5+r()*3)+'" fill="'+(r()>.5?"#6F6A61":"#A8A296")+'"/>';
  out+=lbl(y,bs,"Stone sub-base",L.base); y+=bs;
  out+='<rect x="'+x0+'" y="'+y+'" width="'+w+'" height="'+(380-y)+'" fill="#6B5544"/><text x="'+(x0+12)+'" y="'+(y+24)+'" fill="#F1EDE5" font-size="13" font-family="Mukta,sans-serif">Compacted soil</text>';
  $("xsec").innerHTML=out; $("xsec").style.color="var(--ink)";
}
